CREATE OR REPLACE FUNCTION public.guard_family_portrait_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE changed boolean; BEGIN IF TG_TABLE_NAME='profiles' THEN changed := (to_jsonb(NEW)->'avatar_url') IS DISTINCT FROM (to_jsonb(OLD)->'avatar_url') OR (to_jsonb(NEW)->'avatar_full_url') IS DISTINCT FROM (to_jsonb(OLD)->'avatar_full_url'); ELSE changed := (to_jsonb(NEW)->'photo_url') IS DISTINCT FROM (to_jsonb(OLD)->'photo_url'); END IF; IF changed AND auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'student') OR public.has_role(auth.uid(),'parent')) AND NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director') OR public.has_role(auth.uid(),'teacher')) THEN RAISE EXCEPTION 'นักเรียนและผู้ปกครองไม่สามารถเปลี่ยนรูปโปรไฟล์ได้ กรุณาติดต่อครู' USING ERRCODE='42501'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.guard_family_portrait_change() FROM PUBLIC;
CREATE TRIGGER guard_family_profile_portrait BEFORE UPDATE OF avatar_url,avatar_full_url ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_family_portrait_change();
CREATE TRIGGER guard_family_card_portrait BEFORE UPDATE OF photo_url ON public.students FOR EACH ROW EXECUTE FUNCTION public.guard_family_portrait_change();